entries[204695] = { ["name"] = "Recipe: Cauldron of Extracted Putrescence", ["text"] = "Use: Teaches you how to craft Cauldron of Extracted Putrescence.\nCarefully extract decayed specimens from the Altar of Decay within Brackenhide Hollow for future use.\nRequires Dragon Isles Alchemy (50)\nSell Price:" }
