entries[204704] = { ["name"] = "Adaptive Dracothyst Armguards", ["text"] = "Binds when picked up\nWrist Mail\n277 Armor\n+144 [Agility or Intellect]\n+234 Stamina\n+ 134 Haste\n+ 134 Mastery\nDurability 55 / 55\nEquip: Occasionally you adapt to your current situation for 12 sec.\n\nTaking damage can grant you 170 Versatility and Critical Strike.\n\nCausing critical damage or healing can grant you 170 Mastery and Haste.\nSell Price:" }
entries[204705] = { ["name"] = "Gold Coins", ["text"] = "Quest Item\n\"The weight feels good in your hands.\"" }
entries[204706] = { ["name"] = "Spore Colony Shoulderguards", ["text"] = "Binds when picked up\nShoulder Leather\n258 Armor\n+193 [Agility or Intellect]\n+312 Stamina\n+ 179 Critical Strike\n+ 179 Haste\nDurability 100 / 100\nEquip: Dealing damage with spells and abilities has a chance to apply a stack of Ever-Decaying Spores to your target. At 5 stacks the spores rapidly decay and inflict ( 776 * 10) Nature damage over 10 sec.\n\nSometimes the spores will immediately decay and inflict 776 Nature damage to you.\n\nThis effect is increased by 100% if you equip an item crafted with a Toxified Armor Patch.\nSell Price:" }
entries[204708] = { ["name"] = "Shadowflame-Tempered Armor Patch", ["text"] = "Optional Crafting Reagent\n+35 Recipe Difficulty\nProvides the following property: Dealing damage can inflict stacking Shadowflame damage. Also add Unique-Equipped: Embellished (2).\nUsable with: Dragon Isles recipes for most unembellished Epic armor.\nSell Price:" }
