entries[204712] = { ["name"] = "Brimming Loamm Niffen Supply Satchel", ["text"] = "Binds to Warband\n\"Contains a variety of rewards for those who have proven themselves true allies of the Loamm Niffen.\"\n<Right Click to Open>" }
