entries[204714] = { ["name"] = "Satchel of Healing Spores", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Intellect\nUse: Send the spores to your target, applying a shield that will absorb up to 12207 damage for 15 sec. If the shield breaks before expiring, a cute mushroom will grow at the target's feet. (1 Min Cooldown)\n\"Only true wisdom can make the spores grow.\"\nSell Price:" }
