entries[204717] = { ["name"] = "Splintered Spark of Shadowflame", ["text"] = "Dragonflight Season 2\nBinds when picked up\nUse: Combine two Splintered Spark of Shadowflame to create a Spark of Shadowflame.\nCrafting Reagent\n\"A fragment of a Spark of Shadowflame, obtained once per week from your first Malicia's Hoard or Scentsational Niffen Treasures.\"\nSell Price:" }
