entries[204975] = { ["name"] = "Formula: Enchant Weapon - Shadowflame Wreathe", ["text"] = "Use: Teaches you how to perform the Shadowflame Wreathe enchantment.\nPermanently enchants a weapon to erupt with Shadowflame, causing your damaging spells and abilities to sometimes inflict 26892 Shadowflame damage to your target over 12 sec while instantly inflicting 2241 Shadowflame damage to yourself. Cannot be applied to items lower than level 180.\nRequires Dragon Isles Enchanting (50)\nSell Price:" }
