entries[204978] = { ["name"] = "Formula: Enchant Weapon - Spore Tender", ["text"] = "Binds when picked up\nUse: Teaches you how to perform the Spore Tender enchantment.\nPermanently enchants a weapon to cultivate living spores, causing your healing spells and abilities to occasionally send an Invigorating Spore Cloud to your target. It will grant them 232 of their highest secondary stat for 12 sec. Cannot be applied to items lower than level 180.\nRequires Dragon Isles Enchanting (50)\nSell Price:" }
