entries[205168] = { ["name"] = "Shadowed Impact Buckler", ["text"] = "Binds when picked up\nOff Hand Shield\n2442 Armor\n+128 Strength\n+394 Intellect\n+208 Stamina\n+ 133 Critical Strike\n+ 106 Mastery\nDurability 120 / 120\nEquip: Taking damage has a chance to store stacks of Shadowed Immolation.\n\nAfter receiving 5 stacks, your next ability will release the stored energy dealing 1989 Shadowflame damage split between all enemies within 10 yards. This effect repeats for each stack of Shadowed Immolation.\nSell Price:" }
entries[205169] = { ["name"] = "Glimmer Mushroom", ["text"] = "Quest Item\n\"A delectable foraged mushroom, bursting with earthy flavor and known to be a low calorie source of protein and medicinal properties. Ideal for health-conscious champions in need of sustenance.\"" }
