entries[205191] = { ["name"] = "Underlight Globe", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 342 Mastery\nEquip: Your abilities have a chance to light the globe, drawing the attention of underlight moths. Collecting an attracted moth grants you Underlight Harmony, increasing your Primary Stat by 1408 for 10 sec.\nSell Price:" }
entries[205192] = { ["name"] = "Volatile Crystal Shard", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 Intellect\nEquip: Your damaging spells have a chance to launch the crystal shard at your target which shatters on impact with an enemy, dealing 12669 Physical damage split between nearby enemies.\nSell Price:" }
entries[205193] = { ["name"] = "Sturdy Deepflayer Scute", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 [Agility or Strength or Intellect]\nUse: Strengthen your resolve, increasing Versatility by 1640 for 15 sec. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[205194] = { ["name"] = "Fractured Crystalspine Quill", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 [Agility or Strength]\nUse: Shatter the quill, dealing 42803 Physical damage split between nearby enemies and absorbing 45187 damage for 15 sec. (2 Min Cooldown)\nSell Price:" }
entries[205195] = { ["name"] = "Drakeforged Magma Charm", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 342 Critical Strike\nEquip: Your damaging abilities have a chance to call a magma worm that unleashes a molten volley at your target, dealing up to ( 8153 * 3) Fire damage.\nSell Price:" }
entries[205196] = { ["name"] = "Zaqali Hand Cauldron", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 [Agility or Strength or Intellect]\nUse: Hurl the molten contents, dealing 17286 Fire damage split between nearby enemies and an additional 10021 Fire damage over 8 sec. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[205197] = { ["name"] = "Igneous Shalewing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"You'd be forgiven for mistaking this creature for a flying volcanic rock. Because to some extent, it is.\"\nVendor:\nSaccratros\nZone:\nZaralek Cavern\nCost:\n400" }
