entries[205203] = { ["name"] = "Cobalt Shalewing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Brood of Karokta, raised in the underlight of Zaralek Cavern.\"\nDrop:\nKarokta\nZone:\nZaralek Cavern" }
entries[205204] = { ["name"] = "Flaming Shalewing Subject 01", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Cataloged Shalewing mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The first instance of a flaming shalewing ever discovered. Nine out of ten researchers agree: it's hot!\"\nZone:\nZaralek Cavern\nPublic Event:\nResearchers Under Fire" }
entries[205205] = { ["name"] = "Shadowflame Shalewing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Born from the magma, its carapace was originally molten blobs cooled to form dark-colored volcanic rock. Being imbued by shadowflame has only solidified its unbreakable nature.\"\nAchievement:\nGlory of the Aberrus Raider" }
entries[205207] = { ["name"] = "Morsel Sniffer Reins", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Loamm Niffen.\n\n\"A breed of shalewings trained by the niffen to find the deepest of morsels.\"\nVendor:\nHarlowe Marl\nZone:\nZaralek Cavern\nCost:\n800" }
entries[205208] = { ["name"] = "Sandy Shalewing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The patterns on the wings of that creature resemble sand flowing through an hourglass. One could gaze upon them for ages...\"\nVendor:\nAny Timewalking Vendor\nCost:\n5000" }
entries[205209] = { ["name"] = "Boulder Hauler Reins", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These shalewings have been specially trained to carry large amounts of Barter Boulders for the niffen's bartering activities.\"\nVendor:\nPonzo\nZone:\nZaralek Cavern\nCost:\n85" }
